CREATE TABLE app.marketplace_extension_runtime_status (profile_id uuid PRIMARY KEY, version text NOT NULL, build uuid NOT NULL, mode text NOT NULL, tracking_policy text NOT NULL, tracking_hour integer NOT NULL, accounts jsonb NOT NULL, reported_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE app.marketplace_extension_runtime_status ENABLE ROW LEVEL SECURITY; REVOKE ALL ON app.marketplace_extension_runtime_status FROM public,anon; GRANT SELECT,INSERT,UPDATE ON app.marketplace_extension_runtime_status TO authenticated; CREATE POLICY marketplace_extension_runtime_admin ON app.marketplace_extension_runtime_status TO authenticated USING(app.is_admin()) WITH CHECK(app.is_admin()); CREATE FUNCTION app.marketplace_extension_runtime_report(p_profile_id uuid,p_version text,p_build uuid,p_mode text,p_tracking_policy text,p_tracking_hour integer,p_accounts jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=app,public AS $$ BEGIN IF NOT (auth.uid() IS NOT NULL AND app.is_admin()) THEN RAISE EXCEPTION '管理者認証が必要です'; END IF; IF p_version !~ '^\d+\.\d+\.\d+$' OR length(p_version)>20 OR p_mode NOT IN ('diagnostic','tracking','full') OR p_tracking_policy NOT IN ('inventory-first','legacy') OR p_tracking_hour NOT BETWEEN 0 AND 23 OR jsonb_typeof(p_accounts)<>'array' OR jsonb_array_length(p_accounts)>7 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_accounts) a WHERE a NOT IN ('mercari-1','mercari-2','auctions-1','auctions-2','flea-1','flea-2','rakuma-1')) THEN RAISE EXCEPTION '実行設定の報告が不正です'; END IF; INSERT INTO app.marketplace_extension_runtime_status(profile_id,version,build,mode,tracking_policy,tracking_hour,accounts) VALUES(p_profile_id,p_version,p_build,p_mode,p_tracking_policy,p_tracking_hour,p_accounts) ON CONFLICT(profile_id) DO UPDATE SET version=excluded.version,build=excluded.build,mode=excluded.mode,tracking_policy=excluded.tracking_policy,tracking_hour=excluded.tracking_hour,accounts=excluded.accounts,reported_at=now(); RETURN jsonb_build_object('reported',true); END $$; REVOKE ALL ON FUNCTION app.marketplace_extension_runtime_report(uuid,text,uuid,text,text,integer,jsonb) FROM public,anon; GRANT EXECUTE ON FUNCTION app.marketplace_extension_runtime_report(uuid,text,uuid,text,text,integer,jsonb) TO authenticated;